DEF_CASES="sgemm32|sgemm|-n32||;sgemv|sgemv|-m128 -n128||;vecadd|vecadd|-n16384||;dxa|dxa_copy|-d2|-DVX_CFG_EXT_DXA_ENABLE|;l2mc|sgemm|-n32||--l2cache --cores=2;hbm3|vecadd|-n16384|$HBM3CFG|--l2cache --cores=2;gddr6|sgemv|-m128 -n128|$GDDR6CFG|"
PROF_CASES="prof_p100|sgemv|-m256 -n256||--profile=p100 --cores=4;prof_gtx1080|vecadd|-n65536||--profile=gtx1080 --cores=4;prof_h100|vecadd|-n65536||--profile=h100 --cores=4"
HBM3E_PAR="parity_hbm3e|vecadd|-n16384|-DVX_CFG_PLATFORM_MEMORY_TYPE=HBM3E -DVX_CFG_PLATFORM_MEMORY_NUM_BANKS=4 -DVX_CFG_PLATFORM_MEMORY_DATA_RATE=6400 -DVX_CFG_PLATFORM_MEMORY_BANK_GROUPS=8|--l2cache --cores=2"
HBM3E_MEAS="m_hbm3|vecadd|-n262144|-DVX_CFG_PLATFORM_MEMORY_TYPE=HBM3 -DVX_CFG_PLATFORM_MEMORY_NUM_BANKS=4 -DVX_CFG_PLATFORM_MEMORY_DATA_RATE=6400|--l2cache --cores=8;m_hbm3e|vecadd|-n262144|-DVX_CFG_PLATFORM_MEMORY_TYPE=HBM3E -DVX_CFG_PLATFORM_MEMORY_NUM_BANKS=8 -DVX_CFG_PLATFORM_MEMORY_DATA_RATE=6400|--l2cache --cores=8;m_hbm3e_bg8|vecadd|-n262144|-DVX_CFG_PLATFORM_MEMORY_TYPE=HBM3E -DVX_CFG_PLATFORM_MEMORY_NUM_BANKS=8 -DVX_CFG_PLATFORM_MEMORY_DATA_RATE=6400 -DVX_CFG_PLATFORM_MEMORY_BANK_GROUPS=8|--l2cache --cores=8"
H3="-DVX_CFG_PLATFORM_MEMORY_TYPE=HBM3 -DVX_CFG_PLATFORM_MEMORY_NUM_BANKS=4 -DVX_CFG_PLATFORM_MEMORY_DATA_RATE=6400"
WIN_PAR="parity_window|vecadd|-n16384|$H3 -DVX_CFG_PLATFORM_MEMORY_SCHED_WINDOW=256|--l2cache --cores=2"
WIN_MEAS="m_w32|vecadd|-n262144|$H3|--l2cache --cores=8;m_w256|vecadd|-n262144|$H3 -DVX_CFG_PLATFORM_MEMORY_SCHED_WINDOW=256|--l2cache --cores=8;m_gemv_w32|sgemv|-m1024 -n1024|$H3|--l2cache --cores=8;m_gemv_w256|sgemv|-m1024 -n1024|$H3 -DVX_CFG_PLATFORM_MEMORY_SCHED_WINDOW=256|--l2cache --cores=8"
IC="-DVX_CFG_PLATFORM_MEMORY_TYPE=HBM3E -DVX_CFG_PLATFORM_MEMORY_NUM_BANKS=16 -DVX_CFG_PLATFORM_MEMORY_DATA_RATE=6400 -DVX_CFG_PLATFORM_MEMORY_BANK_GROUPS=8"
IL_PAR="parity_interleave|vecadd|-n16384|$H3 -DVX_CFG_PLATFORM_MEMORY_INTERLEAVE_SIZE=1024|--l2cache --cores=2"
IL_MEAS="m_va_i64|vecadd|-n262144|$IC|--l2cache --cores=8;m_va_i256|vecadd|-n262144|$IC -DVX_CFG_PLATFORM_MEMORY_INTERLEAVE_SIZE=256|--l2cache --cores=8;m_va_i1k|vecadd|-n262144|$IC -DVX_CFG_PLATFORM_MEMORY_INTERLEAVE_SIZE=1024|--l2cache --cores=8;m_gv_i64|sgemv|-m1024 -n1024|$IC|--l2cache --cores=8;m_gv_i256|sgemv|-m1024 -n1024|$IC -DVX_CFG_PLATFORM_MEMORY_INTERLEAVE_SIZE=256|--l2cache --cores=8;m_gv_i1k|sgemv|-m1024 -n1024|$IC -DVX_CFG_PLATFORM_MEMORY_INTERLEAVE_SIZE=1024|--l2cache --cores=8"
AXI_CASES="axi_demo|demo||-DVX_CFG_NUM_CLUSTERS=1 -DVX_CFG_NUM_CORES=1 -DVX_CFG_NUM_WARPS=2 -DVX_CFG_NUM_THREADS=2 -DVX_CFG_ICACHE_DISABLE -DVX_CFG_DCACHE_DISABLE -DVX_CFG_LMEM_DISABLE -DVX_CFG_FPU_TYPE_STD -DPLATFORM_MEMORY_ID_WIDTH=5|;axi_sgemm|sgemm|-n16|-DVX_CFG_NUM_CLUSTERS=1 -DVX_CFG_NUM_CORES=1 -DVX_CFG_NUM_WARPS=2 -DVX_CFG_NUM_THREADS=2 -DVX_CFG_ICACHE_DISABLE -DVX_CFG_DCACHE_DISABLE -DVX_CFG_LMEM_DISABLE -DVX_CFG_FPU_TYPE_STD -DPLATFORM_MEMORY_ID_WIDTH=5|"
FCFG="-DVX_CFG_NUM_CLUSTERS=1 -DVX_CFG_NUM_CORES=1 -DVX_CFG_NUM_WARPS=2 -DVX_CFG_NUM_THREADS=2 -DVX_CFG_ICACHE_DISABLE -DVX_CFG_DCACHE_DISABLE -DVX_CFG_LMEM_DISABLE -DVX_CFG_FPU_TYPE_STD -DPLATFORM_MEMORY_ID_WIDTH=5"
AXI_CASES="axi_demo|demo||$FCFG||AXI_BUS=1 AXI_MEM_MODEL=bank;axi_sgemm|sgemm|-n16|$FCFG||AXI_BUS=1 AXI_MEM_MODEL=bank"
