BW="-n256 -r1 -p0 -u4 -b32"
M2H3="-DVX_CFG_PLATFORM_MEMORY_TYPE=HBM3 -DVX_CFG_PLATFORM_MEMORY_NUM_BANKS=2 -DVX_CFG_PLATFORM_MEMORY_DATA_RATE=6400"
M4E="-DVX_CFG_PLATFORM_MEMORY_TYPE=HBM3E -DVX_CFG_PLATFORM_MEMORY_NUM_BANKS=4 -DVX_CFG_PLATFORM_MEMORY_DATA_RATE=6400"
MEM8="mem8|sgemm||-DVX_CFG_MEM_BLOCK_SIZE=8 -DVX_CFG_LMEM_NUM_BANKS=4 -DVX_CFG_DCACHE_NUM_BANKS=1|"
LEAN="$MEM8;sgemm32|sgemm|-n32||;vecadd|vecadd|-n16384||;l2mc|sgemm|-n32||--l2cache --cores=2;hbm3|vecadd|-n16384|$HBM3CFG|--l2cache --cores=2"
CK="-DVX_CFG_PLATFORM_CLOCK_RATE=1980"
PAR2="vecadd|-n16384"
PA_OFF="pa_off|$PAR2|$CK -DVX_CFG_PLATFORM_MEMORY_TYPE=HBM3E -DVX_CFG_PLATFORM_MEMORY_NUM_BANKS=2 -DVX_CFG_PLATFORM_MEMORY_DATA_RATE=6400|--l2cache --cores=2"
PA_ON="pa_on|$PAR2|$CK -DVX_CFG_PLATFORM_MEMORY_TYPE=HBM3E -DVX_CFG_PLATFORM_MEMORY_NUM_BANKS=2 -DVX_CFG_PLATFORM_MEMORY_DATA_RATE=6400 -DVX_CFG_PLATFORM_MEMORY_BANK_GROUPS=8|--l2cache --cores=2"
PB_OFF="pb_off|$PAR2|$CK $M2H3|--l2cache --cores=2"
PB_ON="pb_on|$PAR2|$CK $M2H3 -DVX_CFG_PLATFORM_MEMORY_SCHED_WINDOW=256|--l2cache --cores=2"
PC_OFF="pc_off|$PAR2|$CK $M2H3|--l2cache --cores=2"
PC_ON="pc_on|$PAR2|$CK $M2H3 -DVX_CFG_PLATFORM_MEMORY_INTERLEAVE_SIZE=1024|--l2cache --cores=2"
BWA="bw_hbm3|bwstream|$BW|$M2H3|--profile=h100 --cores=4;bw_hbm3e|bwstream|$BW|$M4E|--profile=h100 --cores=4;bw_hbm3e_bg8|bwstream|$BW|$M4E -DVX_CFG_PLATFORM_MEMORY_BANK_GROUPS=8|--profile=h100 --cores=4"
BWB="bw_w32|bwstream|$BW|$M2H3|--profile=h100 --cores=4;bw_w256|bwstream|$BW|$M2H3 -DVX_CFG_PLATFORM_MEMORY_SCHED_WINDOW=256|--profile=h100 --cores=4"
BWC="bw_i0|bwstream|$BW|$M4E -DVX_CFG_PLATFORM_MEMORY_BANK_GROUPS=8|--profile=h100 --cores=4;bw_i256|bwstream|$BW|$M4E -DVX_CFG_PLATFORM_MEMORY_BANK_GROUPS=8 -DVX_CFG_PLATFORM_MEMORY_INTERLEAVE_SIZE=256|--profile=h100 --cores=4;bw_i1k|bwstream|$BW|$M4E -DVX_CFG_PLATFORM_MEMORY_BANK_GROUPS=8 -DVX_CFG_PLATFORM_MEMORY_INTERLEAVE_SIZE=1024|--profile=h100 --cores=4"
